-- Update teacher records with their Firebase UIDs
-- These UIDs were generated by the Firebase script on December 6, 2025

-- Teacher 1: Maria Santos - Mathematics
UPDATE teachers 
SET firebase_uid = 'gZfnO8iIJXRJIEoXJzOSv2X43uL2'
WHERE email = 'maria.santos@school.edu';

-- Also update the users table
UPDATE users 
SET firebase_uid = 'gZfnO8iIJXRJIEoXJzOSv2X43uL2'
WHERE email = 'maria.santos@school.edu';

