-- =====================================================
-- VERIFICATION
-- =====================================================

-- Check teachers with Firebase UIDs
SELECT 
  name,
  email,
  firebase_uid,
  position,
  specialization
FROM teachers
WHERE firebase_uid IS NOT NULL
ORDER BY name;

-- Check users with Firebase UIDs
SELECT 
  name,
  email,
  firebase_uid,
  role
FROM users
WHERE firebase_uid IS NOT NULL 
  AND role = 'teacher'
ORDER BY name;

-- =====================================================
-- SUCCESS MESSAGE
-- =====================================================
SELECT '✅ Updated ' || COUNT(*) || ' teachers with Firebase UIDs' as message
FROM teachers 
WHERE firebase_uid IS NOT NULL;
